<?php
require __DIR__ . '/../includes/layout.php';
require_role(['admin']);
$type = $_GET['type'] ?? ''; $id = (int)($_GET['id'] ?? 0); $row = null; $title = 'Record details'; $fields = [];
switch ($type) {
 case 'equipment': $title='Equipment details'; $row=one('SELECT e.*, c.category_name FROM equipment e LEFT JOIN categories c ON c.category_id=e.category_id WHERE e.equipment_id=?',[$id]); $fields=['Equipment'=>'equipment_name','Category'=>'category_name','Description'=>'description','Serial number'=>'serial_number','QR code'=>'qr_code','Status'=>'status','Condition'=>'condition_status','Quantity'=>'quantity','Location'=>'location','Department'=>'department','Purchase date'=>'purchase_date','Last maintenance'=>'last_maintenance','Usage count'=>'usage_count','Created'=>'created_at']; break;
 case 'borrow': $title='Borrow record details'; $row=one('SELECT b.*,e.equipment_name,u.full_name,u.username,u.email,u.department,ap.full_name approved_name FROM borrow_records b JOIN equipment e ON e.equipment_id=b.equipment_id JOIN users u ON u.user_id=b.user_id LEFT JOIN users ap ON ap.user_id=b.approved_by WHERE b.borrow_id=?',[$id]); $fields=['Equipment'=>'equipment_name','Borrower'=>'full_name','Username'=>'username','Email'=>'email','Department'=>'department','Status'=>'status','Requested'=>'created_at','Borrow date'=>'borrow_date','Expected return'=>'expected_return_date','Actual return'=>'actual_return_date','Notes'=>'notes','Condition at borrow'=>'condition_at_borrow','Condition at return'=>'condition_at_return','Approved by'=>'approved_name']; break;
 case 'category': $title='Category details'; $row=one('SELECT c.*, (SELECT COUNT(*) FROM equipment e WHERE e.category_id=c.category_id) item_count FROM categories c WHERE c.category_id=?',[$id]); $fields=['Name'=>'category_name','Description'=>'description','Equipment count'=>'item_count','Created'=>'created_at']; break;
 case 'maintenance': $title='Maintenance details'; $row=one('SELECT m.*,e.equipment_name,e.serial_number FROM maintenance_logs m JOIN equipment e ON e.equipment_id=m.equipment_id WHERE m.log_id=?',[$id]); $fields=['Equipment'=>'equipment_name','Serial number'=>'serial_number','Date'=>'maintenance_date','Description'=>'description','Cost'=>'cost','Technician'=>'technician','Next maintenance'=>'next_maintenance_date','Trigger'=>'trigger_type','Created'=>'created_at']; break;
 case 'fine': $title='Fine details'; $row=one('SELECT f.*,u.full_name,u.username,u.email,b.equipment_id,e.equipment_name FROM fines f JOIN users u ON u.user_id=f.user_id LEFT JOIN borrow_records b ON b.borrow_id=f.borrow_id LEFT JOIN equipment e ON e.equipment_id=b.equipment_id WHERE f.fine_id=?',[$id]); $fields=['User'=>'full_name','Username'=>'username','Email'=>'email','Related equipment'=>'equipment_name','Borrow record ID'=>'borrow_id','Days overdue'=>'days_overdue','Amount'=>'amount','Reason'=>'reason','Status'=>'status','Payment method'=>'payment_method','Payment reference'=>'payment_reference','Paid at'=>'paid_at','Created'=>'created_at']; break;
}
if (!$row) { flash('Record not found.','err'); redirect('admin/dashboard.php'); }
page_start($title,'admin','');
?>
<section class="card glass" style="max-width:850px"><div class="card-head"><h3><?= e($title) ?> #<?= $id ?></h3><a class="btn ghost" href="javascript:history.back()">Back</a></div><div class="fg">
<?php foreach ($fields as $label=>$key): ?><div><label><?= e($label) ?></label><div class="detail-value"><?php $v=$row[$key] ?? ''; if ($key==='cost'||$key==='amount') echo e(money($v)); elseif ($key==='created_at'||(substr($key,-5)==='_date')||$key==='paid_at') echo e($v ? dt($v,'M j, Y g:i A') : '—'); else echo nl2br(e(($v===null||$v==='')?'—':$v)); ?></div></div><?php endforeach; ?>
</div></section><?php page_end();
